package fonts

import "github.com/gabriel/ascii-banner-studio/internal/core/domain"

// NewBanner3DFont es la fuente FIGlet 'banner3-D' (nombre visible 'Banner3-D').
// Generada desde pyfiglet para ampliar la variedad de ASCII.
// Altura: 8. Incluye 95 glyphs ASCII imprimibles (32..126) donde la fuente original los define;
// los ausentes usan el fallback '?' del motor sin panics.
func NewBanner3DFont() domain.Font {
	return domain.Font{
		ID:         "banner3d",
		Name:       "Banner3-D",
		Height:     8,
		Characters: buildFigletCharacters(figlet_banner3dPatterns),
		Fallback:   '?',
	}
}

